//! Precomputed B601-RS per-link convex-hull vertices from `examples/host/app/cad/meshes/*.STL`.
//!
//! Generated by `scripts/extract_hulls.py`. Each slice holds outer boundary
//! points in that link's URDF frame (metres), consumed once by `parry3d_f64`
//! to build exact convex polyhedra for mesh self-collision and table surface
//! clearance without requiring mounted STL files inside PostgreSQL.

pub(crate) struct LinkHullDef {
    pub name: &'static str,
    pub vertices: &'static [[f64; 3]],
}

